import csv

TAX_RATE = 0.1


def load_usage(path):
    with open(path, newline="") as f:
        return [row for row in csv.DictReader(f)]


def invoice_total(rows):
    subtotal = 0.0
    for row in rows:
        subtotal += float(row["units"]) * float(row["unit_price"])
    tax = subtotal * TAX_RATE
    return round(subtotal + tax, 2)


def bill_customers(path, charge):
    by_customer = {}
    for row in load_usage(path):
        by_customer.setdefault(row["customer_id"], []).append(row)
    for customer_id, rows in by_customer.items():
        amount = invoice_total(rows)
        if amount > 0:
            charge(customer_id, int(amount * 100))

