import logging
from datetime import datetime, timezone

log = logging.getLogger(__name__)


def normalise_event(raw, tags=[]):
    event = {
        "id": raw["id"],
        "type": raw.get("type", "unknown").lower(),
        "received_at": datetime.now(timezone.utc).isoformat(),
    }
    if raw.get("priority") == "high":
        tags.append("urgent")
    if raw.get("source") == "mobile":
        tags.append("mobile")
    event["tags"] = tags
    return event


def normalise_batch(raws):
    out = []
    for raw in raws:
        try:
            out.append(normalise_event(raw))
        except KeyError:
            log.warning("skipping event with no id: %r", raw)
    return out

