Payroll uses this to work out pay for casual staff shifts entered as Sydney local times.

from datetime import datetime
from zoneinfo import ZoneInfo

SYDNEY = ZoneInfo("Australia/Sydney")
WEEKEND_LOADING = 1.5


def parse_local(ts):
    return datetime.strptime(ts, "%Y-%m-%d %H:%M").replace(tzinfo=SYDNEY)


def shift_hours(start_ts, end_ts):
    start = parse_local(start_ts)
    end = parse_local(end_ts)
    if end <= start:
        raise ValueError("shift must end after it starts")
    return (end - start).total_seconds() / 3600


def shift_pay_cents(start_ts, end_ts, base_rate_cents):
    hours = shift_hours(start_ts, end_ts)
    rate = base_rate_cents
    if parse_local(start_ts).weekday() >= 5:
        rate = base_rate_cents * WEEKEND_LOADING
    return round(hours * rate)

