BATCH_SIZE = 500


def chunked(items, size):
    num_batches = len(items) // size
    for i in range(num_batches):
        yield items[i * size:(i + 1) * size]


def sync_contacts(contacts, client):
    sent = 0
    for batch in chunked(contacts, BATCH_SIZE):
        try:
            client.upsert_contacts(batch)
            sent += len(batch)
