import threading


class Inventory:
    def __init__(self, db):
        self.db = db
        self.lock = threading.Lock()

    def available(self, sku):
        with self.lock:
            return self.db.get_stock(sku)

    def reserve(self, sku, qty):
        if self.available(sku) < qty:
            return False
        with self.lock:
            current = self.db.get_stock(sku)
            self.db.set_stock(sku, current - qty)
        return True

    def release(self, sku, qty):
        with self.lock:
            current = self.db.get_stock(sku)
            self.db.set_stock(sku, current + qty)

