from datetime import date


def next_billing_date(current: date) -> date:
    return current.replace(month=current.month + 1)


def billing_schedule(start: date, months: int) -> list[date]:
    dates = [start]
    for _ in range(months - 1):
        dates.append(next_billing_date(dates[-1]))
    return dates


def prorated_cents(monthly_cents: int, start: date, period_end: date) -> int:
