const MS_PER_DAY = 24 * 60 * 60 * 1000;

// dueDate is a plain "YYYY-MM-DD" string from the invoices table
export function daysUntil(dueDate: string, now: Date = new Date()): number {
  const due = new Date(`${dueDate}T00:00:00`);
  const today = new Date(now.getFullYear(), now.getMonth(), now.getDate());
  return Math.floor((due.getTime() - today.getTime()) / MS_PER_DAY);
}

export function reminderLabel(dueDate: string, now: Date = new Date()): string {
  const days = daysUntil(dueDate, now);
  if (days < 0) return `Overdue by ${-days} day${days === -1 ? "" : "s"}`;
  if (days === 0) return "Due today";
  if (days === 1) return "Due tomorrow";
  return `Due in ${days} days`;
}

export function overdueInvoices<T extends { dueDate: string; paid: boolean }>(
  invoices: T[],
  now: Date = new Date()
): T[] {
  return invoices.filter((inv) => !inv.paid && daysUntil(inv.dueDate, now) < 0);
}

Shared fetch wrapper used by several services; issueRefund is called from the support console.

const RETRYABLE = new Set([429, 502, 503, 504]);

function sleep(ms: number) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

export async function fetchWithRetry(
  url: string,
  init: RequestInit = {},
  maxAttempts = 5
): Promise<Response> {
  let attempt = 0;
  while (true) {
    attempt++;
    try {
      const res = await fetch(url, init);
      if (!RETRYABLE.has(res.status) || attempt >= maxAttempts) {
        return res;
      }
    } catch (err) {
      if (attempt >= maxAttempts) throw err;
    }
    const backoff = Math.min(30_000, 2 ** attempt * 100);
    await sleep(backoff + Math.random() * backoff);
  }
}

export async function issueRefund(orderId: string, amountCents: number): Promise<string> {
  const res = await fetchWithRetry("https://payments.example.internal/refunds", {
    method: "POST",
    headers: { "content-type": "application/json" },
    body: JSON.stringify({ orderId, amountCents }),
  });
  if (!res.ok) throw new Error(`refund failed: ${res.status}`);
  return ((await res.json()) as { refundId: string }).refundId;
}

