type Reading = { sensorId: string; at: string; value: number | null };

export function averageBySensor(readings: Reading[]): Record<string, number> {
  const sums: Record<string, { total: number; count: number }> = {};
  for (const r of readings) {
    if (!r.value) continue;
    const s = (sums[r.sensorId] ??= { total: 0, count: 0 });
    s.total += r.value;
    s.count += 1;
  }
  const out: Record<string, number> = {};
  for (const [id, { total, count }] of Object.entries(sums)) {
    out[id] = total / count;
  }
  return out;
}

export function latestReading(readings: Reading[], sensorId: string): Reading | undefined {
  return readings
    .filter((r) => r.sensorId === sensorId)
    .sort((a, b) => (a.at < b.at ? 1 : -1))[0];
}

Receives payment events from the provider, which retries deliveries and sometimes sends duplicates at the same time.

// Webhook receiver for payment events from our provider
const crypto = require("crypto");

const processed = new Set();

async function handleWebhook(req, res, { secret, markInvoicePaid }) {
  const signature = req.headers["x-signature"];
  const expected = crypto
    .createHmac("sha256", secret)
    .update(req.rawBody)
    .digest("hex");

  if (signature !== expected) {
    return res.status(401).send("bad signature");
  }

  const event = JSON.parse(req.rawBody);
  if (processed.has(event.id)) {
    return res.status(200).send("duplicate");
  }

  if (event.type === "payment.succeeded") {
    await markInvoicePaid(event.data.invoiceId, event.data.amountCents);
  }
  processed.add(event.id);
  res.status(200).send("ok");
}

module.exports = { handleWebhook };

Called on every login attempt to slow down password guessing.

export class RateLimiter {
  private hits = new Map<string, number[]>();

  constructor(private limit: number, private windowMs: number) {}

  allow(key: string, now = Date.now()): boolean {
    const windowStart = now - this.windowMs;
    const recent = (this.hits.get(key) ?? []).filter((t) => t > windowStart);
    if (recent.length > this.limit) {
      this.hits.set(key, recent);
      return false;
    }
    recent.push(now);
    this.hits.set(key, recent);
    return true;
  }
}

// 5 login attempts per minute per IP
export const loginLimiter = new RateLimiter(5, 60_000);

export function checkLogin(ip: string): { ok: boolean; retryAfterSec?: number } {
  if (!loginLimiter.allow(ip)) {
    return { ok: false, retryAfterSec: 60 };
  }
  return { ok: true };
}

