Used by the API to move credit between two customer wallets.

const { Pool } = require("pg");
const pool = new Pool();

// Moves money between two wallets inside one transaction
async function transfer(fromId, toId, amountCents) {
  if (!Number.isInteger(amountCents) || amountCents <= 0) {
    throw new Error("amount must be a positive whole number of cents");
  }
  const client = await pool.connect();
  try {
    await client.query("BEGIN");
    const { rows } = await client.query(
      "SELECT balance_cents FROM wallets WHERE id = $1",
      [fromId]
    );
    if (rows.length === 0) throw new Error("source wallet not found");
    if (rows[0].balance_cents < amountCents) throw new Error("insufficient funds");
    await client.query(
      "UPDATE wallets SET balance_cents = balance_cents - $1 WHERE id = $2",
      [amountCents, fromId]
    );
    await client.query(
      "UPDATE wallets SET balance_cents = balance_cents + $1 WHERE id = $2",
      [amountCents, toId]
    );
    await client.query("COMMIT");
  } catch (err) {
    await client.query("ROLLBACK");
    throw err;
  }
}

module.exports = { transfer };

