package main

import (
	"fmt"
	"sync"
)

type Result struct {
	URL    string
	Status int
}

// checkAll pings every health endpoint in parallel and returns the results.
func checkAll(urls []string, ping func(string) (int, error)) []Result {
	var wg sync.WaitGroup
	var mu sync.Mutex
	results := make([]Result, 0, len(urls))

	for _, u := range urls {
		wg.Add(1)
		go func() {
			defer wg.Done()
			status, err := ping(u)
			if err != nil {
				status = 0
			}
			mu.Lock()
			results = append(results, Result{URL: u, Status: status})
			mu.Unlock()
		}()
	}
	wg.Wait()
	return results
}

func main() {
	urls := []string{"https://a.example.internal/health", "https://b.example.internal/health"}
	for _, r := range checkAll(urls, func(string) (int, error) { return 200, nil }) {
