	Cents    int64
}

// loadPayouts reads the weekly payout CSV: driver_id,amount_cents
func loadPayouts(path string) ([]Payout, error) {
	f, err := os.Open(path)
	if err != nil {
		return nil, err
	}
	defer f.Close()

	rows, err := csv.NewReader(f).ReadAll()
	if err != nil {
		return nil, err
	}

	var payouts []Payout
	for i, row := range rows {
		if i == 0 {
			continue // header
		}
		cents, _ := strconv.ParseInt(row[1], 10, 64)
		payouts = append(payouts, Payout{DriverID: row[0], Cents: cents})
	}
	return payouts, nil
}

func main() {
	payouts, err := loadPayouts(os.Args[1])
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	var total int64
	for _, p := range payouts {
		total += p.Cents
	}
