	return &TokenCache{items: make(map[string]entry), ttl: ttl}
}

func (c *TokenCache) Get(tenant string, fetch func(string) (string, error)) (string, error) {
	c.mu.RLock()
	e, ok := c.items[tenant]
	c.mu.RUnlock()
	if ok && time.Now().Before(e.expiresAt) {
		return e.value, nil
	}

	token, err := fetch(tenant)
	if err != nil {
		return "", err
	}
	c.mu.Lock()
	c.items[tenant] = entry{value: token, expiresAt: time.Now().Add(c.ttl)}
	c.mu.Unlock()
	return token, nil
}

// Invalidate drops a tenant's token after the upstream rejects it.
func (c *TokenCache) Invalidate(tenant string) {
	c.mu.RLock()
	delete(c.items, tenant)
	c.mu.RUnlock()
}

func main() {
	c := NewTokenCache(5 * time.Minute)
	tok, err := c.Get("acme", func(t string) (string, error) { return "tok-" + t, nil })
	fmt.Println(tok, err)
}

HTTP handler for the invoices API; X-Account-ID is set by our auth proxy.

package main

import (
	"encoding/json"
	"net/http"
	"strconv"
)

type Store interface {
	ListInvoices(accountID string, limit, offset int) ([]Invoice, error)
}

type Invoice struct {
	ID          string `json:"id"`
	AccountID   string `json:"account_id"`
	AmountCents int64  `json:"amount_cents"`
}

func listInvoicesHandler(store Store) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		accountID := r.Header.Get("X-Account-ID")
		if accountID == "" {
			http.Error(w, "missing account", http.StatusUnauthorized)
			return
		}
		limit, err := strconv.Atoi(r.URL.Query().Get("limit"))
		if err != nil || limit <= 0 {
			limit = 50
		}
		offset, _ := strconv.Atoi(r.URL.Query().Get("offset"))

		invoices, err := store.ListInvoices(accountID, limit, offset)
		if err != nil {
			http.Error(w, "could not load invoices", http.StatusInternalServerError)
		}
		w.Header().Set("Content-Type", "application/json")
		json.NewEncoder(w).Encode(invoices)
	}
}

func main() {}
